'use strict';
const SAVE_KEY='lemonade-empire-save-v1';
let saveOK=true,loadingSave=false;
function reward(amount){amount=finiteAmount(amount);clicks=addAmount(clicks,amount);total=addAmount(total,amount);update();saveGame();return amount;}
function rebirthCost(){return finiteAmount(1e6*Math.pow(10,Math.min(rebirths,90)));}
function rebirthReward(){return total<rebirthCost()?0:Math.min(100,1+Math.floor(Math.log10(total/rebirthCost())));}
function renderFun(){if(!$('legacy-stats'))return;const gain=rebirthReward();$('legacy-stats').textContent=`${rebirths} rebirths · ${zest} Zest · permanent ×${statsFmt(1+zest*.25)} earnings`;$('rebirth-info').textContent=gain?`Rebirth now for +${gain} Zest. Your next empire starts stronger.`:`Earn ${fmt(rebirthCost())} this run to rebirth (${fmt(total)} earned).`;$('rebirth').disabled=!gain;$('rebirth').textContent=gain?`Rebirth · +${gain} Zest`:'Keep growing';const now=Date.now();$('delivery').disabled=now<deliveryReady;$('delivery-label').textContent=now<deliveryReady?`Next launch in ${Math.ceil((deliveryReady-now)/1000)}s`:`+${fmt(Math.max(5000,multiplyAmount(rate,30)))} bank clicks · 60s cooldown`;$('festival').disabled=now<festivalReady;$('festival-label').textContent=now<festivalUntil?`Double earnings · ${Math.ceil((festivalUntil-now)/1000)}s left`:now<festivalReady?`Next happy hour in ${Math.ceil((festivalReady-now)/1000)}s`:'Double earnings for 30s · 3 min cooldown';$('arcade-records').textContent=`Arcade records: ${arcadeBest} best flappy run · ${arcadeDodges} squeezers dodged · ${cookiesCaught} cookies caught`;$('save-status').textContent=saveOK?'Progress saves automatically on this device.':'Your browser blocked saving. Keep this tab open to keep playing.';}
function resetExtras(){rebirths=zest=arcadeDodges=arcadeBest=cookiesCaught=deliveries=luckyLemons=festivalUntil=festivalReady=deliveryReady=0;$('golden-lemon').hidden=true;stopArcade();try{localStorage.removeItem(SAVE_KEY);}catch{} }
function performRebirth(){const gain=rebirthReward();if(!gain)return false;const awarded=goals.map(g=>g.awarded),unlocked=achievements;rebirths=Math.min(1e6,rebirths+1);zest=Math.min(1e9,zest+gain);festivalUntil=0;reset(true);achievements=unlocked;goals.forEach((g,i)=>g.awarded=awarded[i]);update();saveGame();notify(`Fresh start! +${gain} Zest · ×${statsFmt(1+zest*.25)} permanent earnings`);return true;}
function saveGame(){if(loadingSave)return;repairNumbers();try{localStorage.setItem(SAVE_KEY,JSON.stringify({v:1,clicks,total,taps,purchases,achievements,rebirths,zest,arcadeDodges,arcadeBest,cookiesCaught,deliveries,luckyLemons,festivalUntil,festivalReady,deliveryReady,items:Object.fromEntries([...upgrades,...generators,...boosts].map(i=>[i.name,i.owned])),awarded:goals.filter(g=>g.awarded).map(g=>g.name),savedAt:Date.now()}));saveOK=true;}catch{saveOK=false;}}
function loadGame(){loadingSave=true;try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return;const s=JSON.parse(raw);if(s.v!==1||!s.items||typeof s.items!=='object')return;clicks=finiteAmount(s.clicks);total=finiteAmount(s.total);taps=finiteAmount(s.taps);purchases=finiteAmount(s.purchases);achievements=s.achievements===true;rebirths=Math.min(1e6,Math.floor(finiteAmount(s.rebirths)));zest=Math.min(1e9,Math.floor(finiteAmount(s.zest)));arcadeDodges=Math.floor(finiteAmount(s.arcadeDodges));arcadeBest=Math.floor(finiteAmount(s.arcadeBest));cookiesCaught=Math.floor(finiteAmount(s.cookiesCaught));deliveries=Math.floor(finiteAmount(s.deliveries));luckyLemons=Math.floor(finiteAmount(s.luckyLemons));const now=Date.now();festivalUntil=Math.min(now+30000,finiteAmount(s.festivalUntil));festivalReady=Math.min(now+180000,finiteAmount(s.festivalReady));deliveryReady=Math.min(now+60000,finiteAmount(s.deliveryReady));for(const i of [...upgrades,...generators,...boosts])i.owned=finiteAmount(s.items[i.name]);const awarded=new Set(Array.isArray(s.awarded)?s.awarded:[]);goals.forEach(g=>g.awarded=awarded.has(g.name));repairNumbers();const offline=Math.min(7200,Math.max(0,(now-finiteAmount(s.savedAt))/1000));const earned=multiplyAmount(multiplyAmount(baseRate,autoMult),offline);clicks=addAmount(clicks,earned);total=addAmount(total,earned);if(earned)notify(`Welcome back! Your businesses earned ${fmt(earned)} clicks (up to 2 hours).`);update();}catch{notify('Could not read this save. A fresh stand is ready.');}finally{loadingSave=false;}}
$('fun-toggle').addEventListener('click',()=>{renderFun();$('fun-dialog').showModal();});$('fun-close').addEventListener('click',()=>$('fun-dialog').close());
$('rebirth').addEventListener('click',()=>{if(!rebirthReward())return;$('rebirth-confirm-info').textContent=`Gain ${rebirthReward()} permanent Zest. Your bank and shop reset to a new stand. Your achievements and arcade records stay.`;$('rebirth-dialog').showModal();});$('cancel-rebirth').addEventListener('click',()=>$('rebirth-dialog').close());$('confirm-rebirth').addEventListener('click',()=>{performRebirth();$('rebirth-dialog').close();});
$('delivery').addEventListener('click',()=>{if(Date.now()<deliveryReady)return;repairNumbers();deliveryReady=Date.now()+60000;deliveries++;const earned=reward(Math.max(5000,multiplyAmount(rate,30)));notify(`Lemon Express delivered! +${fmt(earned)} clicks`);});
$('festival').addEventListener('click',()=>{if(Date.now()<festivalReady)return;festivalUntil=Date.now()+30000;festivalReady=Date.now()+180000;update();saveGame();notify('Happy hour! Double sales and business earnings for 30 seconds.');});
let goldenTimeout;setInterval(()=>{if(document.hidden||$('fun-dialog').open||$('arcade-dialog').open)return;$('golden-lemon').hidden=false;clearTimeout(goldenTimeout);goldenTimeout=setTimeout(()=>$('golden-lemon').hidden=true,12000);},45000);
$('golden-lemon').addEventListener('click',()=>{if($('golden-lemon').hidden)return;$('golden-lemon').hidden=true;luckyLemons++;const earned=reward(Math.max(2500,multiplyAmount(rate,15)));notify(`Golden lemon! +${fmt(earned)} bank clicks`);});
// Both arcade games use the same responsive canvas, with a fixed logical coordinate system.
const canvas=$('arcade'),ctx=canvas.getContext('2d');
let mode='flappy',running=false,raf=0,prevTime=0,runScore=0,runEarned=0,elapsed=0,spawn=0,obstacles=[],falling=[],lemonY=210,velocity=0,basketX=300,leftHeld=false,rightHeld=false;
function stopArcade(){running=false;cancelAnimationFrame(raf);raf=0;leftHeld=rightHeld=false;}
function openArcade(next){stopArcade();mode=next;$('arcade-title').textContent=mode==='flappy'?'Flappy Lemon':'Cosmic Cookie Catch';$('arcade-help').textContent=mode==='flappy'?'Tap the game or press Space / ↑ to flap. Dodge each lemon squeezer for 10,000 clicks. Hit a squeezer or the edge and the run ends.':'Drag in the game or use ← / → to move your tray. Catch cookies for at least 2,000 clicks each. Avoid meteors! Each run lasts 30 seconds.';$('arcade-score').textContent='Ready? Rewards go straight to your bank.';$('arcade-start').textContent='Start game';$('arcade-dialog').showModal();drawArcade();}
$('open-flappy').addEventListener('click',()=>openArcade('flappy'));$('open-cookies').addEventListener('click',()=>openArcade('cookies'));$('arcade-close').addEventListener('click',()=>$('arcade-dialog').close());$('arcade-dialog').addEventListener('close',stopArcade);$('arcade-dialog').addEventListener('cancel',stopArcade);
function startArcade(){stopArcade();runScore=runEarned=elapsed=spawn=0;obstacles=[];falling=[];lemonY=210;velocity=-180;basketX=300;running=true;prevTime=performance.now();$('arcade-start').textContent='Restart run';canvas.focus();raf=requestAnimationFrame(frame);}
$('arcade-start').addEventListener('click',startArcade);
function endArcade(message){stopArcade();arcadeBest=Math.max(arcadeBest,mode==='flappy'?runScore:0);update();saveGame();$('arcade-score').textContent=`${message} ${runScore} ${mode==='flappy'?'dodged':'cookies'} · +${fmt(runEarned)} clicks`;$('arcade-start').textContent='Play again';drawArcade();}
function scoreDodge(){arcadeDodges++;runScore++;runEarned=addAmount(runEarned,10000);reward(10000);}
function stepArcade(dt){elapsed+=dt;spawn+=dt;if(mode==='flappy'){velocity+=660*dt;lemonY+=velocity*dt;if(spawn>1.8){spawn=0;obstacles.push({x:620,gap:95+Math.random()*230,passed:false});}const speed=155+Math.min(80,runScore*3);for(const o of obstacles){o.x-=speed*dt;if(o.x+52<138&&!o.passed){o.passed=true;scoreDodge();}if(o.x<182&&o.x+52>138&&(lemonY-15<o.gap-80||lemonY+15>o.gap+80)){endArcade('Squeezed!');return;}}obstacles=obstacles.filter(o=>o.x>-60);if(lemonY<15||lemonY>405){endArcade('Squeezed!');return;}}else{basketX=Math.max(40,Math.min(560,basketX+((rightHeld?1:0)-(leftHeld?1:0))*360*dt));if(spawn>.45){spawn=0;falling.push({x:25+Math.random()*550,y:-20,meteor:Math.random()<.23});}for(const f of falling){f.y+=180*dt;if(!f.done&&f.y>=350&&f.y<=390&&Math.abs(f.x-basketX)<48){f.done=true;if(f.meteor){endArcade('Meteor bonk!');return;}cookiesCaught++;runScore++;const earned=Math.max(2000,multiplyAmount(rate,2));runEarned=addAmount(runEarned,earned);reward(earned);}}falling=falling.filter(f=>f.y<450&&!f.done);if(elapsed>=30){endArcade('Sweet delivery!');return;}}$('arcade-score').textContent=`${runScore} ${mode==='flappy'?'dodged':'caught'} · +${fmt(runEarned)} clicks${mode==='cookies'?' · '+Math.ceil(30-elapsed)+'s':''}`;}
function drawLemon(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(-.3);ctx.fillStyle='#f0fb57';ctx.beginPath();ctx.ellipse(0,0,22,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7ade92';ctx.beginPath();ctx.ellipse(15,-15,12,5,-.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#243531';ctx.fillRect(5,-3,3,4);ctx.restore();}
function drawArcade(){const g=ctx.createLinearGradient(0,0,0,420);g.addColorStop(0,'#0d2039');g.addColorStop(1,'#345657');ctx.fillStyle=g;ctx.fillRect(0,0,600,420);ctx.fillStyle='#c6e1b0';for(let i=0;i<45;i++){const x=(i*137)%600,y=(i*73)%420;ctx.fillRect(x,y,2,2);}if(mode==='flappy'){for(const o of obstacles){ctx.fillStyle='#7fac8a';ctx.fillRect(o.x,0,52,o.gap-80);ctx.fillRect(o.x,o.gap+80,52,420-o.gap-80);ctx.fillStyle='#e5f891';ctx.fillRect(o.x-5,o.gap-92,62,12);ctx.fillRect(o.x-5,o.gap+80,62,12);ctx.fillStyle='#324d42';for(let i=0;i<4;i++){ctx.fillRect(o.x+8+i*10,o.gap-100,4,8);ctx.fillRect(o.x+8+i*10,o.gap+92,4,8);}}drawLemon(160,lemonY);}else{ctx.textAlign='center';ctx.font='30px sans-serif';for(const f of falling)ctx.fillText(f.meteor?'☄️':'🍪',f.x,f.y);ctx.fillStyle='#effd76';ctx.fillRect(basketX-44,370,88,14);ctx.fillStyle='#a6c349';ctx.fillRect(basketX-37,384,74,10);}if(!running){ctx.fillStyle='#122436b8';ctx.fillRect(0,0,600,420);drawLemon(300,165);ctx.fillStyle='#f2ffae';ctx.textAlign='center';ctx.font='bold 27px sans-serif';ctx.fillText(mode==='flappy'?'FLAPPY LEMON':'COSMIC COOKIE CATCH',300,228);ctx.font='16px sans-serif';ctx.fillText('Press Start game below to play',300,262);}}
function frame(now){if(!running)return;if(document.hidden){prevTime=now;raf=requestAnimationFrame(frame);return;}const dt=Math.min(.04,Math.max(0,(now-prevTime)/1000));prevTime=now;stepArcade(dt);if(!running)return;drawArcade();raf=requestAnimationFrame(frame);}
function steer(event){const r=canvas.getBoundingClientRect();basketX=Math.max(40,Math.min(560,(event.clientX-r.left)/r.width*600));}
canvas.addEventListener('pointerdown',e=>{if(!running)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);if(mode==='flappy')velocity=-265;else steer(e);});canvas.addEventListener('pointermove',e=>{if(running&&mode==='cookies'&&(e.buttons||e.pointerType==='touch'))steer(e);});
document.addEventListener('keydown',e=>{if(!$('arcade-dialog').open||!running)return;if(['Space','ArrowUp','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(mode==='flappy'&&['Space','ArrowUp'].includes(e.code)&&!e.repeat)velocity=-265;if(e.code==='ArrowLeft')leftHeld=true;if(e.code==='ArrowRight')rightHeld=true;});document.addEventListener('keyup',e=>{if(e.code==='ArrowLeft')leftHeld=false;if(e.code==='ArrowRight')rightHeld=false;});window.addEventListener('blur',()=>{leftHeld=rightHeld=false;});
loadGame();renderFun();setInterval(saveGame,2000);window.addEventListener('pagehide',saveGame);document.addEventListener('visibilitychange',()=>{if(document.hidden)saveGame();});$('confirm-reset').addEventListener('click',saveGame);
